import pandas as pd

def invalid_tweets_ii(tweets: pd.DataFrame) -> pd.DataFrame:
    df = tweets.copy()
    if df.empty:
        return pd.DataFrame(columns=['tweet_id'])

    cond1 = df['content'].str.len() > 140
    cond2 = df['content'].str.count('@') > 3
    cond3 = df['content'].str.count('#') > 3

    res = df[cond1 | cond2 | cond3]
    return res[['tweet_id']].sort_values(by='tweet_id')
